package br.com.admeclesial.application.financeiro;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.DizimistaRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DizimistaApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final DizimistaRepository repo; final OrganizacaoEclesialRepository org; final PessoaRepository pessoa; public DizimistaApplicationService(DizimistaRepository r,OrganizacaoEclesialRepository o,PessoaRepository p){repo=r;org=o;pessoa=p;} @Transactional public Dizimista salvar(UUID uuid,DizimistaRequest r){if(seguranca!=null)seguranca.validarAcesso(r.organizacaoEclesialUuid());if(uuid!=null){var atual=repo.findByUuid(uuid).orElseThrow(()->new IllegalArgumentException("Dizimista não encontrado."));if(seguranca!=null)seguranca.validarAcessoId(atual.getOrganizacaoEclesialId());}var o=org.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada."));var pe=pessoa.findByUuid(r.pessoaUuid()).orElseThrow(()->new IllegalArgumentException("Pessoa não encontrada."));if(!o.isAtivo()||!pe.isAtivo())throw new IllegalArgumentException("Organização e pessoa devem estar ativas.");if(r.dataFim()!=null&&r.dataFim().isBefore(r.dataInicio()))throw new IllegalArgumentException("Período do dizimista inválido.");var e=uuid==null?new Dizimista():repo.findByUuid(uuid).orElseThrow(()->new IllegalArgumentException("Dizimista não encontrado."));e.setPessoaId(pe.getId());e.setOrganizacaoEclesialId(o.getId());e.setDataInicio(r.dataInicio());e.setDataFim(r.dataFim());e.setAtivo(r.ativo()==null||r.ativo());e.setObservacao(r.observacao());return repo.save(e);} @Transactional(readOnly=true) public List<Dizimista> listar(){return repo.findAll().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}}
